		resp, ok := resps[id]
		require.Truef(t, ok, "missing response for lease %d", id)
		require.Equalf(t, id, resp.ID, "response grouped under wrong lease ID")
		require.Positivef(t, resp.TTL, "lease %d got non-positive TTL", id)
