	srv := &batchLeaseServer{
		failCode:          codes.Internal,
		failFirst:         1,
		succeedBeforeFail: 2,
	}
	cli := newBatchLeaseClient(t, srv)

	ids := []clientv3.LeaseID{101, 202, 303, 404}

